<script setup>
import RedesignTopbar from './RedesignTopbar.vue';
import { Head, Link, router, usePage } from '@inertiajs/vue3';
import { computed, ref } from 'vue';
import AdminSidebar from './AdminSidebar.vue';

const props = defineProps({ taskBanks: Object, jobs: { type: Array, default: () => [] }, filters: Object });
const page = usePage();
const items = computed(() => props.taskBanks?.data || []);
const search = ref(props.filters?.search || '');
const selectedStatus = ref(props.filters?.status || 'all');
const status = computed(() => props.filters?.status || 'all');
const archiveCandidate = ref(null);
const assessmentLabels = { essay: 'Esai', multiple_choice: 'Pilihan ganda', mixed: 'Campuran', platforming: 'Platforming', word_match: 'Word match' };
const navigate = (overrides = {}) => router.get(route('redesign.task-banks'), { search: search.value.trim() || undefined, status: selectedStatus.value === 'all' ? undefined : selectedStatus.value, ...overrides }, { preserveState: true, preserveScroll: true, replace: true });
const chooseTab = value => { selectedStatus.value = value; navigate({ status: value === 'all' ? undefined : value }); };
const reset = () => { search.value = ''; selectedStatus.value = 'all'; router.get(route('redesign.task-banks'), {}, { preserveState: true, replace: true }); };
const archive = () => {
    if (!archiveCandidate.value) return;
    router.delete(route('admin.task-banks.destroy', archiveCandidate.value.uuid), { preserveScroll: true, onSuccess: () => { archiveCandidate.value = null; } });
};
const restore = bank => router.patch(route('admin.task-banks.restore', bank.uuid), {}, { preserveScroll: true });
</script>

<template>
    <Head title="Task banks" />
    <div class="banks-app"><AdminSidebar /><main>
        <RedesignTopbar breadcrumb="Quest &amp; task bank" />
        <div class="content"><div class="heading"><div><h1>Task banks</h1><p>Bank soal, tipe asesmen, timer, dan konfigurasi game.</p></div><Link class="primary" :href="route('redesign.task-banks.create')">+ Tambah bank</Link></div>
            <div class="tabs" role="group" aria-label="Status task bank"><button v-for="tab in [{ value: 'all', label: 'Semua' }, { value: 'active', label: 'Aktif' }, { value: 'draft', label: 'Draft' }, { value: 'archive', label: 'Arsip' }]" :key="tab.value" type="button" :class="{ active: status === tab.value }" @click="chooseTab(tab.value)">{{ tab.label }}</button></div>
            <form class="filters" @submit.prevent="navigate()"><input v-model="search" aria-label="Cari task bank" placeholder="Cari nama, deskripsi, atau tipe asesmen..." /><select v-model="selectedStatus" aria-label="Filter status"><option value="all">Semua status</option><option value="active">Aktif</option><option value="draft">Draft</option><option value="archive">Arsip</option></select><button type="submit">Filter</button><button type="button" @click="reset">Reset</button></form>
            <p v-if="page.props.flash?.message" class="feedback" role="status">{{ { TASK_BANK_CREATED: 'Task bank berhasil ditambahkan.', TASK_BANK_UPDATED: 'Task bank berhasil diperbarui.', TASK_BANK_DELETED: 'Task bank dipindahkan ke arsip.', TASK_BANK_RESTORED: 'Task bank berhasil dipulihkan.' }[page.props.flash.message] || page.props.flash.message }}</p>
            <section class="panel"><div class="panel-heading"><h2>Daftar task bank</h2><span>{{ taskBanks.total || 0 }} bank</span></div><div v-if="!items.length" class="empty">{{ search ? 'Tidak ada task bank yang cocok.' : 'Belum ada task bank pada tampilan ini.' }}</div><div v-else class="table-wrap"><table><thead><tr><th scope="col">Nama task bank</th><th scope="col">Program</th><th scope="col">Tipe asesmen</th><th scope="col">Soal</th><th scope="col">Durasi</th><th scope="col">Status</th><th scope="col">Aksi</th></tr></thead><tbody><tr v-for="bank in items" :key="bank.uuid"><td><Link v-if="status !== 'archive'" class="bank-name" :href="route('redesign.task-banks.questions', bank.uuid)">{{ bank.name }}</Link><strong v-else>{{ bank.name }}</strong><small v-if="bank.description">{{ bank.description }}</small></td><td>{{ bank.job_role?.name || 'Semua program' }}</td><td>{{ assessmentLabels[bank.assessment_type] || bank.assessment_type }}</td><td>{{ bank.questions_count || 0 }}</td><td>{{ bank.has_time_limit ? `${bank.duration || 0} ${['platforming', 'word_match'].includes(bank.assessment_type) ? 'detik' : 'menit'}` : 'Tanpa timer' }}</td><td><span class="badge" :class="{ draft: !bank.is_active, archived: status === 'archive' }">{{ status === 'archive' ? 'Arsip' : bank.is_active ? 'Aktif' : 'Draft' }}</span></td><td><div class="actions"><button v-if="status === 'archive'" type="button" @click="restore(bank)">Pulihkan</button><template v-else><Link :href="route('redesign.task-banks.questions', bank.uuid)">Kelola soal</Link><Link :href="route('redesign.task-banks.edit', bank.uuid)">Edit</Link><button type="button" class="danger" @click="archiveCandidate = bank">Arsipkan</button></template></div></td></tr></tbody></table></div><div class="footer"><span>Menampilkan {{ items.length }} dari {{ taskBanks.total || 0 }} bank</span><div v-if="taskBanks.links?.length > 3" class="pager"><Link v-for="(link, index) in taskBanks.links" :key="index" :href="link.url || '#'" :class="{ active: link.active, disabled: !link.url }" :aria-disabled="!link.url" preserve-scroll v-html="link.label" /></div></div></section>
        </div>
        <div v-if="archiveCandidate" class="overlay" @click.self="archiveCandidate = null"><section class="dialog confirm" role="dialog" aria-modal="true" aria-labelledby="archive-title"><h2 id="archive-title">Arsipkan task bank?</h2><p>{{ archiveCandidate.name }}</p><div class="dialog-actions"><button type="button" class="secondary" @click="archiveCandidate = null">Batal</button><button type="button" class="danger-button" @click="archive">Arsipkan</button></div></section></div>
    </main></div>
</template>

<style scoped>
